	(270, 1, 'CARNIVAL 8160D-VT-X', 'carnival-8160d-vt-x', '<table class="woocommerce-product-attributes shop_attributes">\n<tbody>\n<tr class="woocommerce-product-attributes-item woocommerce-product-attributes-item--attribute_pa_thuong-hieu">\n<th class="woocommerce-product-attributes-item__label" data-url="https://baoanhstore.vn/thuong-hieu-dong-ho-carnival/">Thương hiệu</th>\n<td class="woocommerce-product-attributes-item__value">Carnival</td>\n</tr>\n<tr class="woocommerce-product-attributes-item woocommerce-product-attributes-item--attribute_pa_xuat-xu">\n<th class="woocommerce-product-attributes-item__label" data-url="">Xuất xứ</th>\n<td class="woocommerce-product-attributes-item__value">Thụy Sĩ</td>\n</tr>\n<tr class="woocommerce-product-attributes-item woocommerce-product-attributes-item--attribute_pa_gioi-tinh">\n<th class="woocommerce-product-attributes-item__label" data-url="">Giới tính</th>\n<td class="woocommerce-product-attributes-item__value">Cặp Đôi</td>\n</tr>\n<tr class="woocommerce-product-attributes-item woocommerce-product-attributes-item--attribute_pa_loai-may">\n<th class="woocommerce-product-attributes-item__label" data-url="">Loại máy</th>\n<td class="woocommerce-product-attributes-item__value">Automatic, Quartz (Pin)</td>\n</tr>\n<tr class="woocommerce-product-attributes-item woocommerce-product-attributes-item--attribute_pa_duong-kinh">\n<th class="woocommerce-product-attributes-item__label" data-url="">Đường kính</th>\n<td class="woocommerce-product-attributes-item__value">34 mm, 41 mm</td>\n</tr>\n<tr class="woocommerce-product-attributes-item woocommerce-product-attributes-item--attribute_pa_chat-lieu-vo">\n<th class="woocommerce-product-attributes-item__label" data-url="https://baoanhstore.vn/thep-316l-va-ma-pvd-trong-che-tac-dong-ho/">Chất liệu vỏ</th>\n<td class="woocommerce-product-attributes-item__value">Thép không gỉ 316L, mạ PVD</td>\n</tr>\n<tr class="woocommerce-product-attributes-item woocommerce-product-attributes-item--attribut