	(1353, 1, 'Đồng hồ CASIO G-SHOCK GA-100BEG-1ADR Chính Hãng', 'dong-ho-casio-g-shock-ga-100beg-1adr-chinh-hang', '<h2 class="product-description__title">Thông tin cơ bản</h2>\n                    \n                    <div class="product-description__section">\n                        \n                            <p data-start="3150" data-end="3392">D&ograve;ng G-SHOCK đen v&agrave; xanh điện tử mới với 5 biến thể thiết kế xoay quanh một bảng m&agrave;u thống nhất. Viền bezel, d&acirc;y đeo v&agrave; mặt đồng hồ đều sử dụng m&agrave;u đen &ndash; m&agrave;u cốt l&otilde;i của thương hiệu; khu vực LCD được nhấn bằng chi tiết xanh điện tử sắc n&eacute;t.</p>\n<p data-start="3394" data-end="3649">Khi bật đ&egrave;n nền, c&aacute;c k&yacute; tự tr&ecirc;n m&agrave;n h&igrave;nh kỹ thuật số ph&aacute;t s&aacute;ng r&otilde; n&eacute;t, gi&uacute;p dễ đọc trong điều kiện &aacute;nh s&aacute;ng yếu. Với nền đen tinh tế c&ugrave;ng độ tương phản sống động của m&agrave;u xanh điện tử, d&ograve;ng sản phẩm mang đến vẻ ngo&agrave;i hiện đại, c&aacute; t&iacute;nh với ấn tượng mạnh mẽ.</p>\n\n<h3>Thông số kỹ thuật</h3>\n<table style="border-collapse: separate; border-spacing: 20px; width: 100%;">\n<tbody>\n<tr>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Chiều cao vỏ (bao gồm chấu)</strong><br />55.0 mm</td>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Chiều ngang vỏ (bao gồm n&uacute;t vặn)</strong><br />51.2 mm</td>\n</tr>\n<tr>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Độ d&agrave;y vỏ</strong><br />16.9 mm</td>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Chất liệu vỏ v&agrave; v&ograve;ng mặt số</strong><br />Nhựa resin&nbsp;</td>\n</tr>\n<tr>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Trọng lượng</strong><br />72 g</td>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>D&acirc;y đeo</strong><br />D&acirc;y đeo nhựa</td>\n</tr>\n<tr>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Mặt k&iacute;nh</strong><br />K&iacute;nh kho&aacute;ng</td>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Cấu tr&uacute;c</strong><br />Ch&ocirc;́ng sốc<br />Chống từ</td>\n</tr>\n<tr>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Chống nước</strong><br />Khả năng chống nước ở độ s&acirc;u 200 m&eacute;t</td>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Th&ocirc;ng tin pin</strong><br />Thời gian sử dụng pin khoảng 2 năm đối với pin CR1220</td>\n</tr>\n</tbody>\n</table>', NULL, NULL, 4268000.00, NULL, 15, 'active', 'GA-100BEG-1ADR', NULL, 'Casio', NULL, NULL, 'quartz', NULL, '["\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-ga-100beg-1adr-chinh-hang.png","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-ga-100beg-1adr-chinh-hang-1.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-ga-100beg-1adr-chinh-hang-2.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-ga-100beg-1adr-chinh-hang-3.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-ga-100beg-1adr-chinh-hang-4.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-ga-100beg-1adr-chinh-hang-5.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-ga-100beg-1adr-chinh-hang-6.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-ga-100beg-1adr-chinh-hang-7.jpg"]', 1, 0, 'NEW', 824, 74, 3.33, 6, NULL, NULL, NULL, NULL, '2026-05-27 04:00:58', '2026-05-29 08:14:56', 3, 1),
	(1354, 1, 'Đồng hồ CASIO G-SHOCK GA-700BEG-1ADR Chính Hãng', 'dong-ho-casio-g-shock-ga-700beg-1adr-chinh-hang', '<h2 class="product-description__title">Thông tin cơ bản</h2>\n                    \n                    <div class="product-description__section">\n                        \n                            <p data-start="3150" data-end="3392">D&ograve;ng G-SHOCK đen v&agrave; xanh điện tử mới với 5 biến thể thiết kế xoay quanh một bảng m&agrave;u thống nhất. Viền bezel, d&acirc;y đeo v&agrave; mặt đồng hồ đều sử dụng m&agrave;u đen &ndash; m&agrave;u cốt l&otilde;i của thương hiệu; khu vực LCD được nhấn bằng chi tiết xanh điện tử sắc n&eacute;t.</p>\n<p data-start="3394" data-end="3649">Khi bật đ&egrave;n nền, c&aacute;c k&yacute; tự tr&ecirc;n m&agrave;n h&igrave;nh kỹ thuật số ph&aacute;t s&aacute;ng r&otilde; n&eacute;t, gi&uacute;p dễ đọc trong điều kiện &aacute;nh s&aacute;ng yếu. Với nền đen tinh tế c&ugrave;ng độ tương phản sống động của m&agrave;u xanh điện tử, d&ograve;ng sản phẩm mang đến vẻ ngo&agrave;i hiện đại, c&aacute; t&iacute;nh với ấn tượng mạnh mẽ.</p>\n\n<h3>Thông số kỹ thuật</h3>\n<table style="border-collapse: separate; border-spacing: 20px; width: 100%;">\n<tbody>\n<tr>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Chiều cao vỏ (bao gồm chấu)</strong><br />57.5 mm</td>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Chiều ngang vỏ (bao gồm n&uacute;t vặn)</strong><br />53.4 mm</td>\n</tr>\n<tr>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Độ d&agrave;y vỏ</strong><br />18.5 mm</td>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Chất liệu vỏ v&agrave; v&ograve;ng mặt số</strong><br />Nhựa resin&nbsp;</td>\n</tr>\n<tr>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Trọng lượng</strong><br />75 g</td>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>D&acirc;y đeo</strong><br />D&acirc;y đeo nhựa</td>\n</tr>\n<tr>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Mặt k&iacute;nh</strong><br />K&iacute;nh kho&aacute;ng</td>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Cấu tr&uacute;c</strong><br />Ch&ocirc;́ng sốc</td>\n</tr>\n<tr>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Chống nước</strong><br />Khả năng chống nước ở độ s&acirc;u 200 m&eacute;t</td>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Th&ocirc;ng tin pin</strong><br />Thời gian sử dụng pin khoảng 5 năm đối với pin CR2016</td>\n</tr>\n</tbody>\n</table>', NULL, NULL, 3706000.00, NULL, 15, 'active', 'GA-700BEG-1ADR', NULL, 'Casio', NULL, NULL, 'quartz', NULL, '["\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-ga-700beg-1adr-chinh-hang.png","\\/backend\\/public\\/image\\/product\\/casio\\/dong-ho-casio-g-shock-ga-700beg-1adr-chinh-hang-1.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-ga-700beg-1adr-chinh-hang-2.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-ga-700beg-1adr-chinh-hang-3.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-ga-700beg-1adr-chinh-hang-4.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-ga-700beg-1adr-chinh-hang-5.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-ga-700beg-1adr-chinh-hang-6.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-ga-700beg-1adr-chinh-hang-7.jpg"]', 1, 0, 'NEW', 775, 38, 3.33, 6, NULL, NULL, NULL, NULL, '2026-05-27 04:00:59', '2026-05-29 08:14:56', 3, 1),
	(1355, 2, 'Đồng hồ CASIO G-SHOCK GM-S2110SR-1ADR Chính Hãng', 'dong-ho-casio-g-shock-gm-s2110sr-1adr-chinh-hang', '<h2 class="product-description__title">Thông tin cơ bản</h2>\n                    \n                    <div class="product-description__section">\n                        \n                            <h2 data-section-id="19oglbs" data-start="5903" data-end="5919">GM-S2110SR</h2>\n<p data-start="5921" data-end="6143">D&ograve;ng GM-S2110 với thiết kế b&aacute;t gi&aacute;c kim loại đặc trưng được lấy cảm hứng từ &aacute;nh s&aacute;ng lấp l&aacute;nh của m&ugrave;a h&egrave;. Mặt số m&agrave;u sử dụng k&iacute;nh phủ lắng đọng hơi ph&acirc;n cực, l&agrave;m thay đổi sắc th&aacute;i t&ugrave;y theo g&oacute;c nh&igrave;n v&agrave; chuyển động cổ tay.</p>\n<p data-start="6145" data-end="6454">Kết hợp với bề mặt ho&agrave;n thiện tinh tế của viền kim loại, thiết kế c&acirc;n bằng sự tinh tế với cảm gi&aacute;c nhẹ nh&agrave;ng, thư th&aacute;i, lấy cảm hứng từ c&aacute;c khu nghỉ dưỡng. K&iacute;ch thước vỏ nhỏ gọn mang lại sự vừa vặn thoải m&aacute;i, ngay cả với cổ tay thon, rất th&iacute;ch hợp để đeo hằng ng&agrave;y cũng như phối đồ theo xu hướng thời trang.</p>\n<p data-start="6456" data-end="6593">C&aacute;c th&agrave;nh phần nhựa ch&iacute;nh của d&acirc;y đeo sử dụng nhựa sinh học, được l&agrave;m từ nguồn hữu cơ t&aacute;i tạo v&agrave; g&oacute;p phần giảm t&aacute;c động đến m&ocirc;i trường.</p>\n<p data-start="6595" data-end="6738">Do việc sử dụng lớp phủ bay hơi đặc biệt tr&ecirc;n k&iacute;nh, m&agrave;u sắc c&oacute; thể thay đổi theo từng mẫu t&ugrave;y v&agrave;o g&oacute;c nh&igrave;n, v&agrave; mặt đồng hồ c&oacute; thể hơi kh&oacute; nh&igrave;n.</p>\n<h2 data-section-id="10qfkor" data-start="6745" data-end="6762">GMA-P2100SR</h2>\n<p data-start="6764" data-end="7020">Những mẫu thuộc d&ograve;ng GMA-P2100 c&oacute; k&iacute;ch thước nhỏ gọn v&agrave; thiết kế gọn g&agrave;ng, tối giản, lấy cảm hứng từ &aacute;nh s&aacute;ng lấp l&aacute;nh của m&ugrave;a h&egrave;. Mặt đồng hồ m&agrave;u sử dụng k&iacute;nh phủ lắng đọng hơi ph&acirc;n cực, với t&ocirc;ng m&agrave;u thay đổi t&ugrave;y theo g&oacute;c nh&igrave;n v&agrave; chuyển động của cổ tay.</p>\n<p data-start="7022" data-end="7290">Kết hợp với vỏ v&agrave; d&acirc;y b&aacute;n trong suốt, thiết kế tạo cảm gi&aacute;c nhẹ nh&agrave;ng, tho&aacute;ng nhẹ, như trong khu nghỉ dưỡng. K&iacute;ch thước nhỏ gọn mang lại sự vừa vặn thoải m&aacute;i cho cổ tay thon gọn, linh hoạt, ph&ugrave; hợp cho việc sử dụng h&agrave;ng ng&agrave;y v&agrave; nhiều phong c&aacute;ch thời trang kh&aacute;c nhau.</p>\n<p data-start="7292" data-end="7435">Do việc sử dụng lớp phủ bay hơi đặc biệt tr&ecirc;n k&iacute;nh, m&agrave;u sắc c&oacute; thể thay đổi theo từng mẫu t&ugrave;y v&agrave;o g&oacute;c nh&igrave;n, v&agrave; mặt đồng hồ c&oacute; thể hơi kh&oacute; nh&igrave;n.</p>\n\n<h3>Thông số kỹ thuật</h3>\n<table style="border-collapse: separate; border-spacing: 20px; width: 100%;">\n<tbody>\n<tr>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Chiều cao vỏ (bao gồm chấu)</strong><br />45.9 mm</td>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Chiều ngang vỏ (bao gồm n&uacute;t vặn)</strong><br />40.5 mm</td>\n</tr>\n<tr>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Độ d&agrave;y vỏ</strong><br />11.0 mm</td>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Chất liệu vỏ v&agrave; v&ograve;ng mặt số</strong><br />Nhựa resin / Th&eacute;p kh&ocirc;ng gỉ</td>\n</tr>\n<tr>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Trọng lượng</strong><br />56 g</td>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>D&acirc;y đeo</strong><br />D&acirc;y đeo nhựa</td>\n</tr>\n<tr>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Mặt k&iacute;nh</strong><br />K&iacute;nh kho&aacute;ng</td>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Cấu tr&uacute;c</strong><br />Ch&ocirc;́ng sốc</td>\n</tr>\n<tr>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Chống nước</strong><br />Khả năng chống nước ở độ s&acirc;u 200 m&eacute;t</td>\n<td style="border-bottom: 1px #cccccc solid; vertical-align: top; width: 45%;"><strong>Th&ocirc;ng tin pin</strong><br />Thời gian sử dụng pin khoảng 3 năm đối với pin CR1025</td>\n</tr>\n</tbody>\n</table>', NULL, NULL, 7900000.00, NULL, 15, 'active', 'GM-S2110SR-1ADR', NULL, 'Casio', NULL, NULL, 'quartz', NULL, '["\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-gm-s2110sr-1adr-chinh-hang.png","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-gm-s2110sr-1adr-chinh-hang-1.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-gm-s2110sr-1adr-chinh-hang-2.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-gm-s2110sr-1adr-chinh-hang-3.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-gm-s2110sr-1adr-chinh-hang-4.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-gm-s2110sr-1adr-chinh-hang-5.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-gm-s2110sr-1adr-chinh-hang-6.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-gm-s2110sr-1adr-chinh-hang-7.jpg"]', 1, 0, 'NEW', 588, 144, 3.33, 6, NULL, NULL, NULL, NULL, '2026-05-27 04:01:00', '2026-05-29 08:14:56', 5, 1),
	(1356, 1, 'Đồng hồ Casio Edifice EQB-1300DC-3ADF Chính Hãng', 'dong-ho-casio-edifice-eqb-1300dc-3adf-chinh-hang', '<h2 class="product-description__title">Thông tin cơ bản</h2>\n                    \n                    <div class="product-description__section">\n                        \n                            <p data-start="5111" data-end="5434">EQB-1300 l&agrave; mẫu chủ lực của EDIFICE, thể hiện triết l&yacute; thương hiệu về Tốc độ &amp; Th&ocirc;ng minh. Được thiết kế để mang lại cảm gi&aacute;c l&aacute;i xe th&uacute; vị v&agrave; vẻ đẹp chức năng mang t&iacute;nh th&ocirc;ng minh tr&ecirc;n cổ tay, mẫu đồng hồ kết hợp giữa độ d&agrave;y vỏ mỏng 9,5 mm với đường k&iacute;nh vỏ 39,5 mm, mang lại cả sự thoải m&aacute;i khi đeo v&agrave; vẻ ngo&agrave;i tinh tế.</p>\n<p data-start="5436" data-end="5726">Mặt số c&oacute; họa tiết lấy cảm hứng từ nội thất &ocirc; t&ocirc; cao cấp, vạch chỉ giờ 3D v&agrave; viền th&eacute;p kh&ocirc;ng gỉ được gia c&ocirc;ng cắt ch&iacute;nh x&aacute;c tạo th&ecirc;m vẻ s&aacute;ng b&oacute;ng kim loại trang nh&atilde;. Vỏ th&eacute;p kh&ocirc;ng gỉ chắc chắn, d&acirc;y đeo H-link v&agrave; kh&oacute;a gập chắc chắn thể hiện đầy đủ chất lượng cũng như kết cấu của vật liệu.</p>\n<p data-start="5728" data-end="5984">Về chức năng, kết nối Bluetooth&reg; với điện thoại th&ocirc;ng minh cho c&aacute;c t&iacute;nh năng chỉnh giờ, T&igrave;m điện thoại, Thời gian &amp; địa điểm v&agrave; điều chỉnh giờ m&ugrave;a h&egrave; tự động. Khi được kết nối với ứng dụng chuy&ecirc;n dụng, ngay cả c&aacute;c c&agrave;i đặt phức tạp cũng dễ d&agrave;ng thực hiện.</p>\n<p data-start="5986" data-end="6226">Đồng hồ c&ograve;n được trang bị Tough Solar để tạo năng lượng ổn định, mặt k&iacute;nh sapphire, khả năng chống nước 100m, chức năng bấm giờ (chronograph) v&agrave; lịch tự động đầy đủ, ph&ugrave; hợp cho việc sử dụng h&agrave;ng ng&agrave;y, m&ocirc;i trường c&ocirc;ng sở v&agrave; cả khi l&aacute;i xe.</p>\n<p data-start="6228" data-end="6395">Với sự kết hợp giữa ho&agrave;n thiện ch&iacute;nh x&aacute;c v&agrave; chức năng ti&ecirc;n tiến, d&ograve;ng EQB-1300 d&agrave;nh cho những ai y&ecirc;u th&iacute;ch sự c&acirc;n bằng giữa tốc độ v&agrave; tr&iacute; th&ocirc;ng minh một c&aacute;ch c&acirc;n bằng.</p>\n\n<h3>Thông số kỹ thuật</h3>\n<table style="border-spacing: 20px; width: 100%; border-collapse: separate; height: 271px;">\n<tbody>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Chiều cao vỏ (bao gồm chấu)</strong> <br />46.5 mm</td>\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Chiều ngang vỏ (bao gồm n&uacute;t vặn)</strong> <br />39.5 mm</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Độ d&agrave;y vỏ</strong> <br />9.5 mm</td>\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Chất liệu vỏ v&agrave; v&ograve;ng mặt số</strong><br />Th&eacute;p kh&ocirc;ng gỉ m&agrave;u x&aacute;m</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Trọng lượng</strong> <br />129 g</td>\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>D&acirc;y đeo</strong> <br />D&acirc;y đeo kim loại m&agrave;u x&aacute;m<br />Kh&oacute;a gập 3 với 1 lần nhấn</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Mặt k&iacute;nh</strong> <br />K&iacute;nh Sapphire nguy&ecirc;n khối</td>\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;">&nbsp;</td>\n</tr>\n<tr style="height: 127px;">\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 127px;"><strong>Chống nước</strong> <br />Khả năng chống nước ở độ s&acirc;u 100 m&eacute;t</td>\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 127px;"><strong data-sider-select-id="c7c1226b-8a6a-4d45-982e-4543ae2b78e8">Th&ocirc;ng tin pin</strong><br />Pin sạc năng lượng mặt trời<br />- 5 th&aacute;ng đối với pin sạc (trong điều kiện sử dụng b&igrave;nh thường, kh&ocirc;ng tiếp x&uacute;c với &aacute;nh s&aacute;ng sau khi được sạc đầy)<br />- 18 th&aacute;ng đối với pin sạc (khi được bảo quản trong b&oacute;ng tối ho&agrave;n to&agrave;n v&agrave; bật chức năng tiết kiệm năng lượng sau khi được sạc đầy)</td>\n</tr>\n</tbody>\n</table>', NULL, NULL, 12775000.00, NULL, 15, 'active', 'EQB-1300DC-3ADF', NULL, 'Casio', NULL, NULL, 'quartz', NULL, '["\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-eqb-1300dc-3adf-chinh-hang.png","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-eqb-1300dc-3adf-chinh-hang-1.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-eqb-1300dc-3adf-chinh-hang-2.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-eqb-1300dc-3adf-chinh-hang-3.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-eqb-1300dc-3adf-chinh-hang-4.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-eqb-1300dc-3adf-chinh-hang-5.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-eqb-1300dc-3adf-chinh-hang-6.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-eqb-1300dc-3adf-chinh-hang-7.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-eqb-1300dc-3adf-chinh-hang-8.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-eqb-1300dc-3adf-chinh-hang-9.jpg"]', 1, 0, 'NEW', 1155, 21, 3.33, 6, NULL, NULL, NULL, NULL, '2026-05-27 04:01:00', '2026-05-29 08:14:56', 4, 1),
	(1357, 1, 'Đồng hồ CASIO G-SHOCK DW-6900JV-1DR Chính Hãng', 'dong-ho-casio-g-shock-dw-6900jv-1dr-chinh-hang', '<h2 class="product-description__title">Thông tin cơ bản</h2>\n                    \n                    <div class="product-description__section">\n                        \n                            <p data-start="5236" data-end="5543">Kể từ khi ra mắt v&agrave;o năm 1983, G-SHOCK đ&atilde; kh&ocirc;ng ngừng ph&aacute;t triển c&aacute;c dự &aacute;n hợp t&aacute;c lấy cảm hứng từ nhiều nền văn h&oacute;a v&agrave; lĩnh vực s&aacute;ng tạo kh&aacute;c nhau. Sự hợp t&aacute;c mới nhất n&agrave;y kết hợp G-SHOCK với nghệ sĩ - nh&agrave; thiết kế Joshua Vides, người nổi tiếng với phong c&aacute;ch vẽ tay mang cảm hứng truyện tranh đặc trưng.</p>\n<p data-start="5545" data-end="5823">Bộ sưu tập bao gồm hai mẫu: DW-6900, nổi bật với n&uacute;t bấm ph&iacute;a trước v&agrave; thiết kế 3 m&agrave;n h&igrave;nh hiển thị, v&agrave; DW-5600, được định h&igrave;nh bởi vỏ h&igrave;nh vu&ocirc;ng biểu tượng. Đồ họa đơn sắc đặc trưng của Joshua Vides được &aacute;p dụng tr&ecirc;n to&agrave;n bộ từng chiếc đồng hồ, từ mặt số đến viền v&agrave; d&acirc;y đeo.</p>\n<p data-start="5825" data-end="6236">DW-6900JV với nền đen kết hợp đồ họa trắng v&agrave; lớp ho&agrave;n thiện mờ tạo n&ecirc;n vẻ ngo&agrave;i sắc n&eacute;t, tinh tế. Ngược lại, DW-5600JV với nền trắng kết hợp đồ họa đen v&agrave; lớp ho&agrave;n thiện b&oacute;ng tạo ấn tượng thị gi&aacute;c mạnh mẽ. Cả hai mẫu đều thể hiện t&aacute;c phẩm vẽ tay của Joshua Vides, trong khi việc bật đ&egrave;n nền LED sẽ tiết lộ họa tiết &ldquo;Cone&rdquo; đặc trưng của &ocirc;ng. Những mẫu phi&ecirc;n bản đặc biệt n&agrave;y đi k&egrave;m hộp thiết kế ri&ecirc;ng độc đ&aacute;o.</p>\n<p data-start="6238" data-end="6703"><strong data-start="6238" data-end="6257">Về Joshua Vides</strong><br data-start="6257" data-end="6260" />Joshua Vides l&agrave; một nghệ sĩ v&agrave; nh&agrave; thiết kế đương đại được biết đến tr&ecirc;n to&agrave;n cầu, nổi tiếng với phong c&aacute;ch vẽ tay đen trắng đặc trưng. Lấy cảm hứng từ truyện tranh, nghệ thuật đường phố v&agrave; thiết kế c&ocirc;ng nghiệp, &ocirc;ng biến những vật dụng h&agrave;ng ng&agrave;y, phương tiện v&agrave; kh&ocirc;ng gian th&agrave;nh những m&ocirc;i trường đồ họa hai chiều nổi bật. Hoạt động s&aacute;ng tạo đa lĩnh vực của &ocirc;ng bao gồm tranh tường, sắp đặt, đi&ecirc;u khắc v&agrave; hợp t&aacute;c thương hiệu tr&ecirc;n to&agrave;n thế giới.</p>\n\n<h3>Thông số kỹ thuật</h3>\n<table style="border-collapse: separate; border-spacing: 20px; width: 100%; height: 180px;">\n<tbody>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Chiều cao vỏ (bao gồm chấu)</strong><br />53.2 mm</td>\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Chiều ngang vỏ (bao gồm n&uacute;t vặn)</strong><br />50.0 mm</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Độ d&agrave;y vỏ</strong><br />18.7 mm</td>\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Chất liệu vỏ v&agrave; v&ograve;ng mặt số</strong><br />Nhựa resin&nbsp;</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Trọng lượng</strong><br />67 g</td>\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>D&acirc;y đeo</strong><br />D&acirc;y đeo nhựa</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Mặt k&iacute;nh</strong><br />K&iacute;nh kho&aacute;ng</td>\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Cấu tr&uacute;c</strong><br />Ch&ocirc;́ng sốc</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Chống nước</strong><br />Khả năng chống nước ở độ s&acirc;u 200 m&eacute;t</td>\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Th&ocirc;ng tin pin</strong><br />Thời gian sử dụng pin khoảng 5 năm đối với pin CR2016</td>\n</tr>\n</tbody>\n</table>', NULL, NULL, 4836000.00, NULL, 15, 'active', 'DW-6900JV-1DR', NULL, 'Casio', NULL, NULL, 'quartz', NULL, '["\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-dw-6900jv-1dr-chinh-hang.png","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-dw-6900jv-1dr-chinh-hang-1.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-dw-6900jv-1dr-chinh-hang-2.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-dw-6900jv-1dr-chinh-hang-3.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-dw-6900jv-1dr-chinh-hang-4.png","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-dw-6900jv-1dr-chinh-hang-5.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-dw-6900jv-1dr-chinh-hang-6.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-dw-6900jv-1dr-chinh-hang-7.png","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-dw-6900jv-1dr-chinh-hang-8.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-dw-6900jv-1dr-chinh-hang-9.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-dw-6900jv-1dr-chinh-hang-10.jpg"]', 1, 0, 'NEW', 879, 55, 3.33, 6, NULL, NULL, NULL, NULL, '2026-05-27 04:01:01', '2026-05-29 08:14:56', 3, 1),
	(1358, 1, 'Đồng hồ Casio Edifice EFK-110D-1ADR Chính Hãng', 'dong-ho-casio-edifice-efk-110d-1adr-chinh-hang', '<h2 class="product-description__title">Thông tin cơ bản</h2>\n                    \n                    <div class="product-description__section">\n                        \n                            <p data-start="3881" data-end="4069">EDIFICE AUTOMATIC EFK-110D l&agrave; một mẫu đồng hồ tự động ba kim được ph&aacute;t triển d&agrave;nh cho những người y&ecirc;u th&iacute;ch xe thể thao, tiếp nối tinh thần đua xe thể thao m&agrave; CASIO EDIFICE đ&atilde; định h&igrave;nh.</p>\n<p data-start="4071" data-end="4326">Vỏ 38mm nhỏ gọn sở hữu mặt số kim loại tạo h&igrave;nh bằng c&ocirc;ng nghệ điện h&oacute;a với kết cấu gợi nhớ đến carbon r&egrave;n, mang đến cho đồng hồ diện mạo vừa thể thao vừa tinh tế. C&aacute;c cọc số nổi, viền bezel sắc n&eacute;t v&agrave; thiết kế vỏ t&aacute;o bạo tạo n&ecirc;n một tổng thể năng động.</p>\n<p data-start="4328" data-end="4502">Mặt k&iacute;nh sapphire chống trầy xước c&oacute; độ trong suốt cao, đảm bảo khả năng hiển thị r&otilde; n&eacute;t. Đồng hồ được trang bị bộ m&aacute;y tự động Nhật Bản với dự trữ năng lượng khoảng 42 giờ.</p>\n<p data-start="4504" data-end="4699">Nắp lưng trong suốt gi&uacute;p người đeo quan s&aacute;t bộ m&aacute;y chuyển động, l&agrave;m nổi bật sức hấp dẫn độc đ&aacute;o của đồng hồ cơ. Với khả năng chống nước 100m, EFK-110D mang lại sự linh hoạt cho sử dụng h&agrave;ng ng&agrave;y.</p>\n\n<h3>Thông số kỹ thuật</h3>\n<table style="border-spacing: 20px; width: 100%; border-collapse: separate; height: 198px;">\n<tbody>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Chiều cao vỏ (bao gồm chấu)</strong> <br />43.0 mm</td>\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Chiều ngang vỏ (bao gồm n&uacute;t vặn)</strong> <br />38.0 mm</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Độ d&agrave;y vỏ</strong> <br />11.8 mm</td>\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Chất liệu vỏ v&agrave; v&ograve;ng mặt số</strong> <br />Th&eacute;p kh&ocirc;ng gỉ</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Trọng lượng</strong> <br />143 g</td>\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>D&acirc;y đeo</strong> <br />D&acirc;y đeo th&eacute;p kh&ocirc;ng gỉ<br />Kh&oacute;a gập 3 với 1 lần nhấn</td>\n</tr>\n<tr style="height: 54px;">\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 54px;"><strong>Mặt k&iacute;nh</strong> <br />K&iacute;nh Sapphire nguy&ecirc;n khối</td>\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 54px;">&nbsp;</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Chống nước</strong> <br />Khả năng chống nước ở độ s&acirc;u 100 m&eacute;t</td>\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Th&ocirc;ng tin pin - Đồng hồ cơ</strong> <br />Thời gian trữ c&oacute;t khoảng 42 giờ khi được l&ecirc;n c&oacute;t đầy đủ</td>\n</tr>\n</tbody>\n</table>', NULL, NULL, 11013000.00, NULL, 15, 'active', 'EFK-110D-1ADR', NULL, 'Casio', NULL, NULL, 'quartz', NULL, '["\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-efk-110d-1adr-chinh-hang.png","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-efk-110d-1adr-chinh-hang-1.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-efk-110d-1adr-chinh-hang-2.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-efk-110d-1adr-chinh-hang-3.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-efk-110d-1adr-chinh-hang-4.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-efk-110d-1adr-chinh-hang-5.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-efk-110d-1adr-chinh-hang-6.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-efk-110d-1adr-chinh-hang-7.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-efk-110d-1adr-chinh-hang-8.jpg"]', 1, 0, 'NEW', 1143, 67, 3.33, 6, NULL, NULL, NULL, NULL, '2026-05-27 04:01:02', '2026-05-29 08:14:56', 1, 1),
	(1359, 1, 'Đồng hồ Casio Edifice EQB-1300D-5ADF Chính Hãng', 'dong-ho-casio-edifice-eqb-1300d-5adf-chinh-hang', '<h2 class="product-description__title">Thông tin cơ bản</h2>\n                    \n                    <div class="product-description__section">\n                        \n                            <p data-start="5111" data-end="5434">EQB-1300 l&agrave; mẫu chủ lực của EDIFICE, thể hiện triết l&yacute; thương hiệu về Tốc độ &amp; Th&ocirc;ng minh. Được thiết kế để mang lại cảm gi&aacute;c l&aacute;i xe th&uacute; vị v&agrave; vẻ đẹp chức năng mang t&iacute;nh th&ocirc;ng minh tr&ecirc;n cổ tay, mẫu đồng hồ kết hợp giữa độ d&agrave;y vỏ mỏng 9,5 mm với đường k&iacute;nh vỏ 39,5 mm, mang lại cả sự thoải m&aacute;i khi đeo v&agrave; vẻ ngo&agrave;i tinh tế.</p>\n<p data-start="5436" data-end="5726">Mặt số c&oacute; họa tiết lấy cảm hứng từ nội thất &ocirc; t&ocirc; cao cấp, vạch chỉ giờ 3D v&agrave; viền th&eacute;p kh&ocirc;ng gỉ được gia c&ocirc;ng cắt ch&iacute;nh x&aacute;c tạo th&ecirc;m vẻ s&aacute;ng b&oacute;ng kim loại trang nh&atilde;. Vỏ th&eacute;p kh&ocirc;ng gỉ chắc chắn, d&acirc;y đeo H-link v&agrave; kh&oacute;a gập chắc chắn thể hiện đầy đủ chất lượng cũng như kết cấu của vật liệu.</p>\n<p data-start="5728" data-end="5984">Về chức năng, kết nối Bluetooth&reg; với điện thoại th&ocirc;ng minh cho c&aacute;c t&iacute;nh năng chỉnh giờ, T&igrave;m điện thoại, Thời gian &amp; địa điểm v&agrave; điều chỉnh giờ m&ugrave;a h&egrave; tự động. Khi được kết nối với ứng dụng chuy&ecirc;n dụng, ngay cả c&aacute;c c&agrave;i đặt phức tạp cũng dễ d&agrave;ng thực hiện.</p>\n<p data-start="5986" data-end="6226">Đồng hồ c&ograve;n được trang bị Tough Solar để tạo năng lượng ổn định, mặt k&iacute;nh sapphire, khả năng chống nước 100m, chức năng bấm giờ (chronograph) v&agrave; lịch tự động đầy đủ, ph&ugrave; hợp cho việc sử dụng h&agrave;ng ng&agrave;y, m&ocirc;i trường c&ocirc;ng sở v&agrave; cả khi l&aacute;i xe.</p>\n<p data-start="6228" data-end="6395">Với sự kết hợp giữa ho&agrave;n thiện ch&iacute;nh x&aacute;c v&agrave; chức năng ti&ecirc;n tiến, d&ograve;ng EQB-1300 d&agrave;nh cho những ai y&ecirc;u th&iacute;ch sự c&acirc;n bằng giữa tốc độ v&agrave; tr&iacute; th&ocirc;ng minh một c&aacute;ch c&acirc;n bằng.</p>\n\n<h3>Thông số kỹ thuật</h3>\n<table style="border-spacing: 20px; width: 100%; border-collapse: separate; height: 271px;">\n<tbody>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Chiều cao vỏ (bao gồm chấu)</strong> <br />46.5 mm</td>\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Chiều ngang vỏ (bao gồm n&uacute;t vặn)</strong> <br />39.5 mm</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Độ d&agrave;y vỏ</strong> <br />9.5 mm</td>\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Chất liệu vỏ v&agrave; v&ograve;ng mặt số</strong><br />Th&eacute;p kh&ocirc;ng gỉ</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Trọng lượng</strong> <br />129 g</td>\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>D&acirc;y đeo</strong> <br />D&acirc;y đeo kim loại<br />Kh&oacute;a gập 3 với 1 lần nhấn</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Mặt k&iacute;nh</strong> <br />K&iacute;nh Sapphire nguy&ecirc;n khối</td>\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;">&nbsp;</td>\n</tr>\n<tr style="height: 127px;">\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 127px;"><strong>Chống nước</strong> <br />Khả năng chống nước ở độ s&acirc;u 100 m&eacute;t</td>\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 127px;"><strong data-sider-select-id="c7c1226b-8a6a-4d45-982e-4543ae2b78e8">Th&ocirc;ng tin pin</strong><br />Pin sạc năng lượng mặt trời<br />- 5 th&aacute;ng đối với pin sạc (trong điều kiện sử dụng b&igrave;nh thường, kh&ocirc;ng tiếp x&uacute;c với &aacute;nh s&aacute;ng sau khi được sạc đầy)<br />- 18 th&aacute;ng đối với pin sạc (khi được bảo quản trong b&oacute;ng tối ho&agrave;n to&agrave;n v&agrave; bật chức năng tiết kiệm năng lượng sau khi được sạc đầy)</td>\n</tr>\n</tbody>\n</table>', NULL, NULL, 11013000.00, NULL, 15, 'active', 'EQB-1300D-5ADF', NULL, 'Casio', NULL, NULL, 'quartz', NULL, '["\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-eqb-1300d-5adf-chinh-hang.png","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-eqb-1300d-5adf-chinh-hang-1.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-eqb-1300d-5adf-chinh-hang-2.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-eqb-1300d-5adf-chinh-hang-3.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-eqb-1300d-5adf-chinh-hang-4.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-eqb-1300d-5adf-chinh-hang-5.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-eqb-1300d-5adf-chinh-hang-6.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-eqb-1300d-5adf-chinh-hang-7.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-eqb-1300d-5adf-chinh-hang-8.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-eqb-1300d-5adf-chinh-hang-9.jpg"]', 1, 0, 'NEW', 427, 80, 3.33, 6, NULL, NULL, NULL, NULL, '2026-05-27 04:01:03', '2026-05-29 08:14:56', 2, 1),
	(1360, 1, 'Đồng hồ Casio Edifice EFK-110D-7ADR Chính Hãng', 'dong-ho-casio-edifice-efk-110d-7adr-chinh-hang', '<h2 class="product-description__title">Thông tin cơ bản</h2>\n                    \n                    <div class="product-description__section">\n                        \n                            <p data-start="3881" data-end="4069">EDIFICE AUTOMATIC EFK-110D l&agrave; một mẫu đồng hồ tự động ba kim được ph&aacute;t triển d&agrave;nh cho những người y&ecirc;u th&iacute;ch xe thể thao, tiếp nối tinh thần đua xe thể thao m&agrave; CASIO EDIFICE đ&atilde; định h&igrave;nh.</p>\n<p data-start="4071" data-end="4326">Vỏ 38mm nhỏ gọn sở hữu mặt số kim loại tạo h&igrave;nh bằng c&ocirc;ng nghệ điện h&oacute;a với kết cấu gợi nhớ đến carbon r&egrave;n, mang đến cho đồng hồ diện mạo vừa thể thao vừa tinh tế. C&aacute;c cọc số nổi, viền bezel sắc n&eacute;t v&agrave; thiết kế vỏ t&aacute;o bạo tạo n&ecirc;n một tổng thể năng động.</p>\n<p data-start="4328" data-end="4502">Mặt k&iacute;nh sapphire chống trầy xước c&oacute; độ trong suốt cao, đảm bảo khả năng hiển thị r&otilde; n&eacute;t. Đồng hồ được trang bị bộ m&aacute;y tự động Nhật Bản với dự trữ năng lượng khoảng 42 giờ.</p>\n<p data-start="4504" data-end="4699">Nắp lưng trong suốt gi&uacute;p người đeo quan s&aacute;t bộ m&aacute;y chuyển động, l&agrave;m nổi bật sức hấp dẫn độc đ&aacute;o của đồng hồ cơ. Với khả năng chống nước 100m, EFK-110D mang lại sự linh hoạt cho sử dụng h&agrave;ng ng&agrave;y.</p>\n\n<h3>Thông số kỹ thuật</h3>\n<table style="border-spacing: 20px; width: 100%; border-collapse: separate; height: 198px;">\n<tbody>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Chiều cao vỏ (bao gồm chấu)</strong> <br />43.0 mm</td>\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Chiều ngang vỏ (bao gồm n&uacute;t vặn)</strong> <br />38.0 mm</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Độ d&agrave;y vỏ</strong> <br />11.8 mm</td>\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Chất liệu vỏ v&agrave; v&ograve;ng mặt số</strong> <br />Th&eacute;p kh&ocirc;ng gỉ</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Trọng lượng</strong> <br />143 g</td>\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>D&acirc;y đeo</strong> <br />D&acirc;y đeo th&eacute;p kh&ocirc;ng gỉ<br />Kh&oacute;a gập 3 với 1 lần nhấn</td>\n</tr>\n<tr style="height: 54px;">\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 54px;"><strong>Mặt k&iacute;nh</strong> <br />K&iacute;nh Sapphire nguy&ecirc;n khối</td>\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 54px;">&nbsp;</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Chống nước</strong> <br />Khả năng chống nước ở độ s&acirc;u 100 m&eacute;t</td>\n<td style="border-bottom: 1px solid #cccccc; width: 45%; vertical-align: top; height: 36px;"><strong>Th&ocirc;ng tin pin - Đồng hồ cơ</strong> <br />Thời gian trữ c&oacute;t khoảng 42 giờ khi được l&ecirc;n c&oacute;t đầy đủ</td>\n</tr>\n</tbody>\n</table>', NULL, NULL, 11013000.00, NULL, 15, 'active', 'EFK-110D-7ADR', NULL, 'Casio', NULL, NULL, 'quartz', NULL, '["\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-efk-110d-7adr-chinh-hang.png","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-efk-110d-7adr-chinh-hang-1.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-efk-110d-7adr-chinh-hang-2.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-efk-110d-7adr-chinh-hang-3.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-efk-110d-7adr-chinh-hang-4.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-efk-110d-7adr-chinh-hang-5.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-efk-110d-7adr-chinh-hang-6.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-efk-110d-7adr-chinh-hang-7.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-efk-110d-7adr-chinh-hang-8.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-edifice-efk-110d-7adr-chinh-hang-9.jpg"]', 1, 0, 'NEW', 1264, 40, 3.33, 6, NULL, NULL, NULL, NULL, '2026-05-27 04:01:03', '2026-05-29 08:14:56', 1, 1),
	(1361, 2, 'Đồng hồ Casio Baby-G BGA-15K-6ADR Chính Hãng', 'dong-ho-casio-baby-g-bga-15k-6adr-chinh-hang', '<h2 class="product-description__title">Thông tin cơ bản</h2>\n                    \n                    <div class="product-description__section">\n                        \n                            <p data-start="4289" data-end="4513">Mẫu đồng hồ d&ograve;ng BABY-G PLUS kim số với 4 phi&ecirc;n bản m&agrave;u pastel nhẹ nh&agrave;ng. Được thiết kế để dễ d&agrave;ng phối đồ, c&oacute; thể đeo tr&ecirc;n cổ tay hoặc th&aacute;o ra khỏi d&acirc;y v&agrave; đặt v&agrave;o gi&aacute; đỡ silicone để sử dụng như một charm/m&oacute;c treo độc đ&aacute;o.</p>\n<p data-start="4515" data-end="4776">Gi&aacute; đỡ bằng silicone c&oacute; thể được t&ugrave;y chỉnh với sticker hoặc trang tr&iacute; để ph&ugrave; hợp với sở th&iacute;ch c&aacute; nh&acirc;n. Với bề mặt ho&agrave;n thiện mờ, cả th&acirc;n đồng hồ lẫn gi&aacute; đỡ đều c&oacute; c&aacute;c t&ocirc;ng m&agrave;u pastel nhẹ nh&agrave;ng tạo vẻ ngo&agrave;i dịu mắt, ph&ugrave; hợp với phong c&aacute;ch nữ t&iacute;nh v&agrave; thoải m&aacute;i.</p>\n<p data-start="4778" data-end="5015">Mặt đồng hồ c&oacute; lớp ho&agrave;n thiện &aacute;nh nhũ tinh tế, với c&aacute;c chữ số Ả Rập tại vị tr&iacute; 12 v&agrave; 6 giờ gi&uacute;p dễ xem giờ. M&agrave;n h&igrave;nh hiển thị ng&agrave;y thay đổi thiết kế h&agrave;ng ng&agrave;y, th&ecirc;m yếu tố thị gi&aacute;c vui nhộn th&ocirc;ng qua c&aacute;c ph&ocirc;ng chữ v&agrave; m&agrave;u sắc kh&aacute;c nhau.</p>\n<p data-start="5017" data-end="5142">Ngo&agrave;i cấu tr&uacute;c chống sốc BABY-G, đồng hồ c&ograve;n c&oacute; khả năng chống nước 100m, đảm bảo t&iacute;nh thực tiễn trong cuộc sống h&agrave;ng ng&agrave;y.</p>\n<p data-start="5144" data-end="5322">Việc trang tr&iacute; l&agrave; t&ugrave;y theo người d&ugrave;ng thực hiện. Tr&aacute;nh bảo quản ở nơi c&oacute; &aacute;nh nắng trực tiếp hoặc m&ocirc;i trường nhiệt độ, độ ẩm cao. Việc gắn d&acirc;y kim loại c&oacute; thể l&agrave;m hỏng c&aacute;c lỗ d&acirc;y.</p>\n\n<h3>Thông số kỹ thuật</h3>\n<table style="border-collapse: separate; border-spacing: 20px; width: 100%; height: 180px;">\n<tbody>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Chiều cao vỏ (bao gồm chấu)</strong><br />43.5 mm</td>\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Chiều ngang vỏ (bao gồm n&uacute;t vặn)</strong><br />42.4 mm</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Độ d&agrave;y vỏ</strong><br />11.5 mm</td>\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Chất liệu vỏ v&agrave; v&ograve;ng mặt số</strong><br />Nhựa resin&nbsp;</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Trọng lượng</strong><br />35 g</td>\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>D&acirc;y đeo</strong><br />D&acirc;y đeo nhựa</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Mặt k&iacute;nh</strong><br />K&iacute;nh kho&aacute;ng</td>\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Cấu tr&uacute;c</strong><br />Ch&ocirc;́ng sốc</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Chống nước</strong><br />Khả năng chống nước ở độ s&acirc;u 100 m&eacute;t</td>\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Th&ocirc;ng tin pin</strong><br />Thời gian sử dụng pin khoảng 3 năm đối với pin SR920SW</td>\n</tr>\n</tbody>\n</table>', NULL, NULL, 3058000.00, NULL, 15, 'active', 'BGA-15K-6ADR', NULL, 'Casio', NULL, NULL, 'quartz', NULL, '["\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-baby-g-bga-15k-6adr-chinh-hang.png","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-baby-g-bga-15k-6adr-chinh-hang-1.png","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-baby-g-bga-15k-6adr-chinh-hang-2.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-baby-g-bga-15k-6adr-chinh-hang-3.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-baby-g-bga-15k-6adr-chinh-hang-4.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-baby-g-bga-15k-6adr-chinh-hang-5.png","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-baby-g-bga-15k-6adr-chinh-hang-6.png","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-baby-g-bga-15k-6adr-chinh-hang-7.png","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-baby-g-bga-15k-6adr-chinh-hang-8.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-baby-g-bga-15k-6adr-chinh-hang-9.jpg"]', 1, 0, 'NEW', 513, 137, 3.33, 6, NULL, NULL, NULL, NULL, '2026-05-27 04:01:04', '2026-05-29 08:14:56', 5, 1),
	(1362, 1, 'Đồng hồ CASIO G-SHOCK DW-5600JV-7DR Chính Hãng', 'dong-ho-casio-g-shock-dw-5600jv-7dr-chinh-hang', '<h2 class="product-description__title">Thông tin cơ bản</h2>\n                    \n                    <div class="product-description__section">\n                        \n                            <p data-start="5236" data-end="5543">Kể từ khi ra mắt v&agrave;o năm 1983, G-SHOCK đ&atilde; kh&ocirc;ng ngừng ph&aacute;t triển c&aacute;c dự &aacute;n hợp t&aacute;c lấy cảm hứng từ nhiều nền văn h&oacute;a v&agrave; lĩnh vực s&aacute;ng tạo kh&aacute;c nhau. Sự hợp t&aacute;c mới nhất n&agrave;y kết hợp G-SHOCK với nghệ sĩ - nh&agrave; thiết kế Joshua Vides, người nổi tiếng với phong c&aacute;ch vẽ tay mang cảm hứng truyện tranh đặc trưng.</p>\n<p data-start="5545" data-end="5823">Bộ sưu tập bao gồm hai mẫu: DW-6900, nổi bật với n&uacute;t bấm ph&iacute;a trước v&agrave; thiết kế 3 m&agrave;n h&igrave;nh hiển thị, v&agrave; DW-5600, được định h&igrave;nh bởi vỏ h&igrave;nh vu&ocirc;ng biểu tượng. Đồ họa đơn sắc đặc trưng của Joshua Vides được &aacute;p dụng tr&ecirc;n to&agrave;n bộ từng chiếc đồng hồ, từ mặt số đến viền v&agrave; d&acirc;y đeo.</p>\n<p data-start="5825" data-end="6236">DW-6900JV với nền đen kết hợp đồ họa trắng v&agrave; lớp ho&agrave;n thiện mờ tạo n&ecirc;n vẻ ngo&agrave;i sắc n&eacute;t, tinh tế. Ngược lại, DW-5600JV với nền trắng kết hợp đồ họa đen v&agrave; lớp ho&agrave;n thiện b&oacute;ng tạo ấn tượng thị gi&aacute;c mạnh mẽ. Cả hai mẫu đều thể hiện t&aacute;c phẩm vẽ tay của Joshua Vides, trong khi việc bật đ&egrave;n nền LED sẽ tiết lộ họa tiết &ldquo;Cone&rdquo; đặc trưng của &ocirc;ng. Những mẫu phi&ecirc;n bản đặc biệt n&agrave;y đi k&egrave;m hộp thiết kế ri&ecirc;ng độc đ&aacute;o.</p>\n<p data-start="6238" data-end="6703"><strong data-start="6238" data-end="6257">Về Joshua Vides</strong><br data-start="6257" data-end="6260" />Joshua Vides l&agrave; một nghệ sĩ v&agrave; nh&agrave; thiết kế đương đại được biết đến tr&ecirc;n to&agrave;n cầu, nổi tiếng với phong c&aacute;ch vẽ tay đen trắng đặc trưng. Lấy cảm hứng từ truyện tranh, nghệ thuật đường phố v&agrave; thiết kế c&ocirc;ng nghiệp, &ocirc;ng biến những vật dụng h&agrave;ng ng&agrave;y, phương tiện v&agrave; kh&ocirc;ng gian th&agrave;nh những m&ocirc;i trường đồ họa hai chiều nổi bật. Hoạt động s&aacute;ng tạo đa lĩnh vực của &ocirc;ng bao gồm tranh tường, sắp đặt, đi&ecirc;u khắc v&agrave; hợp t&aacute;c thương hiệu tr&ecirc;n to&agrave;n thế giới.</p>\n\n<h3>Thông số kỹ thuật</h3>\n<table style="border-collapse: separate; border-spacing: 20px; width: 100%; height: 180px;">\n<tbody>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Chiều cao vỏ (bao gồm chấu)</strong><br />48.9 mm</td>\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Chiều ngang vỏ (bao gồm n&uacute;t vặn)</strong><br />42.8 mm</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Độ d&agrave;y vỏ</strong><br />13.4 mm</td>\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Chất liệu vỏ v&agrave; v&ograve;ng mặt số</strong><br />Nhựa resin&nbsp;</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Trọng lượng</strong><br />52 g</td>\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>D&acirc;y đeo</strong><br />D&acirc;y đeo nhựa</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Mặt k&iacute;nh</strong><br />K&iacute;nh kho&aacute;ng</td>\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Cấu tr&uacute;c</strong><br />Ch&ocirc;́ng sốc</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Chống nước</strong><br />Khả năng chống nước ở độ s&acirc;u 200 m&eacute;t</td>\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Th&ocirc;ng tin pin</strong><br />Thời gian sử dụng pin khoảng 5 năm đối với pin CR2016</td>\n</tr>\n</tbody>\n</table>', NULL, NULL, 4836000.00, NULL, 15, 'active', 'DW-5600JV-7DR', NULL, 'Casio', NULL, NULL, 'quartz', NULL, '["\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-dw-5600jv-7dr-chinh-hang.png","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-dw-5600jv-7dr-chinh-hang-1.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-dw-5600jv-7dr-chinh-hang-2.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-dw-5600jv-7dr-chinh-hang-3.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-dw-5600jv-7dr-chinh-hang-4.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-dw-5600jv-7dr-chinh-hang-5.png","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-dw-5600jv-7dr-chinh-hang-6.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-dw-5600jv-7dr-chinh-hang-7.png","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-dw-5600jv-7dr-chinh-hang-8.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-dw-5600jv-7dr-chinh-hang-9.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-g-shock-dw-5600jv-7dr-chinh-hang-10.jpg"]', 1, 0, 'NEW', 1361, 104, 3.33, 6, NULL, NULL, NULL, NULL, '2026-05-27 04:01:05', '2026-05-29 08:14:56', 3, 1),
	(1363, 2, 'Đồng hồ Casio Baby-G BGA-15K-7ADR Chính Hãng', 'dong-ho-casio-baby-g-bga-15k-7adr-chinh-hang', '<h2 class="product-description__title">Thông tin cơ bản</h2>\n                    \n                    <div class="product-description__section">\n                        \n                            <p data-start="4289" data-end="4513">Mẫu đồng hồ d&ograve;ng BABY-G PLUS kim số với 4 phi&ecirc;n bản m&agrave;u pastel nhẹ nh&agrave;ng. Được thiết kế để dễ d&agrave;ng phối đồ, c&oacute; thể đeo tr&ecirc;n cổ tay hoặc th&aacute;o ra khỏi d&acirc;y v&agrave; đặt v&agrave;o gi&aacute; đỡ silicone để sử dụng như một charm/m&oacute;c treo độc đ&aacute;o.</p>\n<p data-start="4515" data-end="4776">Gi&aacute; đỡ bằng silicone c&oacute; thể được t&ugrave;y chỉnh với sticker hoặc trang tr&iacute; để ph&ugrave; hợp với sở th&iacute;ch c&aacute; nh&acirc;n. Với bề mặt ho&agrave;n thiện mờ, cả th&acirc;n đồng hồ lẫn gi&aacute; đỡ đều c&oacute; c&aacute;c t&ocirc;ng m&agrave;u pastel nhẹ nh&agrave;ng tạo vẻ ngo&agrave;i dịu mắt, ph&ugrave; hợp với phong c&aacute;ch nữ t&iacute;nh v&agrave; thoải m&aacute;i.</p>\n<p data-start="4778" data-end="5015">Mặt đồng hồ c&oacute; lớp ho&agrave;n thiện &aacute;nh nhũ tinh tế, với c&aacute;c chữ số Ả Rập tại vị tr&iacute; 12 v&agrave; 6 giờ gi&uacute;p dễ xem giờ. M&agrave;n h&igrave;nh hiển thị ng&agrave;y thay đổi thiết kế h&agrave;ng ng&agrave;y, th&ecirc;m yếu tố thị gi&aacute;c vui nhộn th&ocirc;ng qua c&aacute;c ph&ocirc;ng chữ v&agrave; m&agrave;u sắc kh&aacute;c nhau.</p>\n<p data-start="5017" data-end="5142">Ngo&agrave;i cấu tr&uacute;c chống sốc BABY-G, đồng hồ c&ograve;n c&oacute; khả năng chống nước 100m, đảm bảo t&iacute;nh thực tiễn trong cuộc sống h&agrave;ng ng&agrave;y.</p>\n<p data-start="5144" data-end="5322">Việc trang tr&iacute; l&agrave; t&ugrave;y theo người d&ugrave;ng thực hiện. Tr&aacute;nh bảo quản ở nơi c&oacute; &aacute;nh nắng trực tiếp hoặc m&ocirc;i trường nhiệt độ, độ ẩm cao. Việc gắn d&acirc;y kim loại c&oacute; thể l&agrave;m hỏng c&aacute;c lỗ d&acirc;y.</p>\n\n<h3>Thông số kỹ thuật</h3>\n<table style="border-collapse: separate; border-spacing: 20px; width: 100%; height: 180px;">\n<tbody>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Chiều cao vỏ (bao gồm chấu)</strong><br />43.5 mm</td>\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Chiều ngang vỏ (bao gồm n&uacute;t vặn)</strong><br />42.4 mm</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Độ d&agrave;y vỏ</strong><br />11.5 mm</td>\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Chất liệu vỏ v&agrave; v&ograve;ng mặt số</strong><br />Nhựa resin&nbsp;</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Trọng lượng</strong><br />35 g</td>\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>D&acirc;y đeo</strong><br />D&acirc;y đeo nhựa</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Mặt k&iacute;nh</strong><br />K&iacute;nh kho&aacute;ng</td>\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Cấu tr&uacute;c</strong><br />Ch&ocirc;́ng sốc</td>\n</tr>\n<tr style="height: 36px;">\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Chống nước</strong><br />Khả năng chống nước ở độ s&acirc;u 100 m&eacute;t</td>\n<td style="border-bottom: 1px solid #cccccc; vertical-align: top; width: 45%; height: 36px;"><strong>Th&ocirc;ng tin pin</strong><br />Thời gian sử dụng pin khoảng 3 năm đối với pin SR920SW</td>\n</tr>\n</tbody>\n</table>', NULL, NULL, 3058000.00, NULL, 15, 'active', 'BGA-15K-7ADR', NULL, 'Casio', NULL, NULL, 'quartz', NULL, '["\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-baby-g-bga-15k-7adr-chinh-hang.png","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-baby-g-bga-15k-7adr-chinh-hang-1.png","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-baby-g-bga-15k-7adr-chinh-hang-2.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-baby-g-bga-15k-7adr-chinh-hang-3.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-baby-g-bga-15k-7adr-chinh-hang-4.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-baby-g-bga-15k-7adr-chinh-hang-5.png","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-baby-g-bga-15k-7adr-chinh-hang-6.png","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-baby-g-bga-15k-7adr-chinh-hang-7.png","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-baby-g-bga-15k-7adr-chinh-hang-8.jpg","\\/backend\\/public\\/image\\/product\\/casio\\/2026\\/05\\/dong-ho-casio-baby-g-bga-15k-7adr-chinh-hang-9.jpg"]', 1, 0, 'NEW', 1455, 23, 3.33, 6, NULL, NULL, NULL, NULL, '2026-05-27 04:01:06', '2026-05-29 08:14:56', 5, 1),
