INSERT INTO `reviews` (`id`, `product_id`, `user_id`, `user_name`, `order_id`, `rating`, `title`, `comment`, `is_anonymous`, `status`, `reject_reason`, `shop_reply`, `shop_reply_by`, `shop_reply_at`, `helpful_count`, `is_edited`, `edited_at`, `created_at`, `updated_at`) VALUES
	(1, 16, 2, 'Nguyễn Minh An', 101, 5, 'Tuyệt tác thời gian, hoàn thiện cực kỳ sắc nét!', 'Tôi rất hài lòng với chất lượng hoàn thiện của mẫu đồng hồ này. Kim và cọc số sáng bóng dưới ánh sáng, dây đeo ôm tay thoải mái. Hộp đựng sang trọng phù hợp làm quà tặng. Dịch vụ tư vấn của shop cực kỳ chu đáo, giao hàng nhanh.', 0, 'approved', NULL, 'Cảm ơn anh An đã tin tưởng mua sắm và dành lời khen tốt đẹp cho Venix Watch!', NULL, '2026-05-30 07:51:42', 0, 0, NULL, '2026-05-31 14:51:42', '2026-05-31 14:51:42'),
	(2, 16, 3, 'Trần Thu Bình', 102, 5, 'Đẹp hơn cả trong hình, máy chạy êm và chuẩn giờ', 'Sau một tuần đeo thử thấy máy chạy vô cùng ổn định, sai số rất ít. Mặt kính sapphire chống trầy tốt, tôi vô tình va quẹt nhẹ vài lần nhưng không một vết xước. Sẽ tiếp tục ủng hộ shop các mẫu tiếp theo.', 0, 'approved', NULL, 'Venix Watch rất hân hạnh được phục vụ chị Bình. Chúc chị luôn có những trải nghiệm tuyệt vời cùng sản phẩm!', NULL, '2026-05-30 07:51:42', 0, 0, NULL, '2026-05-31 14:51:42', '2026-05-31 14:51:42'),
	(3, 16, 4, 'Lê Quốc Cường', 103, 4, 'Đồng hồ rất đẹp, phong cách lịch lãm cổ điển', 'Sản phẩm đúng như mô tả, đóng gói rất cẩn thận bằng nhiều lớp chống sốc. Hộp và thẻ bảo hành đầy đủ. Chỉ có một điểm nhỏ là dây da ban đầu hơi cứng một chút, đeo khoảng 3 ngày thì mềm ra ôm khít tay.', 0, 'approved', NULL, 'Cảm ơn anh Cường đã đóng góp ý kiến. Dây da tự nhiên cao cấp thường sẽ mềm mại và ôm tay hơn sau vài ngày sử dụng ạ!', NULL, '2026-05-30 07:51:42', 0, 0, NULL, '2026-05-31 14:51:42', '2026-05-31 14:51:42'),
	(4, 16, 5, 'Phạm Hoàng Danh', 104, 3, 'Sản phẩm tạm ổn, giao hàng hơi lâu', 'Thiết kế đẹp, chất lượng gia công ở mức khá tốt so với tầm giá. Tuy nhiên đơn hàng của mình bị trễ mất 2 ngày so với dự kiến ban đầu làm nhỡ mất dịp tặng sinh nhật bạn bè. Shop cần cải thiện khâu vận chuyển.', 1, 'approved', NULL, 'Venix Watch thành thật xin lỗi anh Danh vì sự cố giao hàng chậm trễ của bên đối tác vận chuyển. Shop sẽ làm việc lại để đẩy nhanh tốc độ giao hàng ạ!', NULL, '2026-05-30 07:51:42', 0, 0, NULL, '2026-05-31 14:51:42', '2026-05-31 14:51:42'),
	(5, 16, 6, 'Đỗ Minh Tuấn', 105, 2, 'Kích thước hơi to so với mô tả, đeo không vừa lắm', 'Chất lượng đồng hồ thì ổn nhưng size mặt kính và độ dày hơi to so với tay mình. Lúc đặt hàng cứ nghĩ đeo vừa, khi nhận đeo thử thấy nặng tay và vướng víu. Hy vọng shop hỗ trợ đổi sang size nhỏ hơn.', 0, 'approved', NULL, 'Dạ Venix Watch có chính sách đổi trả trong vòng 30 ngày đối với sản phẩm còn nguyên tem mác và chưa qua sử dụng ạ. Nhân viên shop sẽ liên hệ ngay để hỗ trợ anh Tuấn đổi mẫu phù hợp hơn nhé!', NULL, '2026-05-30 07:51:42', 0, 0, NULL, '2026-05-31 14:51:42', '2026-05-31 14:51:42'),
	(6, 16, 7, 'Ngô Quốc Khánh', 106, 1, 'Nhận hàng bị xước nhẹ ở mặt đáy', 'Khá thất vọng vì khi bóc seal ra kiểm tra thấy phần nắp đáy sau có một vết xước mảnh. Mặc dù đeo vào không nhìn thấy nhưng cảm giác nhận sản phẩm mới không được trọn vẹn. Mong shop kiểm tra kỹ hơn trước khi gửi.', 0, 'approved', NULL, 'Thành thật xin lỗi anh Khánh vì trải nghiệm chưa trọn vẹn này. Venix Watch cam kết đổi mới 100% sản phẩm khác cho anh ngay lập tức. Nhân viên hỗ trợ sẽ liên hệ xử lý ngay ạ!', NULL, '2026-05-30 07:51:42', 0, 0, NULL, '2026-05-31 14:51:42', '2026-05-31 14:51:42'),
	(7, 17, 2, 'Nguyễn Minh An', 109, 5, 'Tuyệt tác thời gian, hoàn thiện cực kỳ sắc nét!', 'Tôi rất hài lòng với chất lượng hoàn thiện của mẫu đồng hồ này. Kim và cọc số sáng bóng dưới ánh sáng, dây đeo ôm tay thoải mái. Hộp đựng sang trọng phù hợp làm quà tặng. Dịch vụ tư vấn của shop cực kỳ chu đáo, giao hàng nhanh.', 0, 'approved', NULL, 'Cảm ơn anh An đã tin tưởng mua sắm và dành lời khen tốt đẹp cho Venix Watch!', NULL, '2026-05-30 07:51:43', 0, 0, NULL, '2026-05-31 14:51:43', '2026-05-31 14:51:43'),
