	('brand_name', 'Venix Watch', '2026-05-28 08:35:24'),
	('hero_banners', '[{"img":"https:\\/\\/images.pexels.com\\/photos\\/190819\\/pexels-photo-190819.jpeg?auto=compress&cs=tinysrgb&w=1260&h=750&dpr=2","eyebrow":"Bộ Sưu Tập Mới 2025","title":"Đỉnh Cao Tinh Xảo","subtitle":"Khám phá những mẫu đồng hồ chính hãng cao cấp được tuyển chọn kỹ lưỡng nhất.","cta":"Khám Phá Ngay","ctaHref":"\\/nam"},{"img":"https:\\/\\/images.pexels.com\\/photos\\/280250\\/pexels-photo-280250.jpeg?auto=compress&cs=tinysrgb&w=1260&h=750&dpr=2","eyebrow":"Sale - Đến 40% Off","title":"Ưu Đãi Không Thể Bỏ Lỡ","subtitle":"Những mẫu hot nhất, giá tốt nhất. Số lượng có hạn - đặt hàng ngay hôm nay.","cta":"Mua Ngay","ctaHref":"\\/sale"},{"img":"https:\\/\\/images.pexels.com\\/photos\\/277390\\/pexels-photo-277390.jpeg?auto=compress&cs=tinysrgb&w=1260&h=750&dpr=2","eyebrow":"Phong Cách Vĩnh Cửu","title":"Thời Gian Là Nghệ Thuật","subtitle":"Mỗi chiếc đồng hồ là một tác phẩm nghệ thuật, nói lên cá tính riêng của bạn.","cta":"Xem Bộ Sưu Tập","ctaHref":"\\/nu"},{"img":"https:\\/\\/images.pexels.com\\/photos\\/190819\\/pexels-photo-190819.jpeg","eyebrow":"Bộ Sưu Tập Mới 2026","title":"Đỉnh Cao Phong Cách","subtitle":"Khám phá ngay các dòng sản phẩm chất lượng nhất.","cta":"Khám Phá","ctaHref":"\\/nam"}]', '2026-05-29 08:57:25'),
	('home_sections', '{"announcement_bar":{"messages":["Miễn phí vận chuyển đơn hàng trên 500.000đ","Đổi trả trong 30 ngày - Bảo hành 2 năm chính hãng","Dùng code WELCOME10 giảm 10% đơn hàng đầu tiên"]},"promo_banner":{"title":"Mua 1 Tặng 1 — Ưu đãi 50%","code":"BOGOSO","buttons":[{"label":"Shop Nam","href":"\\/nam"},{"label":"Shop Nữ","href":"\\/nu"}]},"brand_story":{"title":"DONG HO ANH TUAN","subtitle":"Kể từ năm 2012","description":"Chúng tôi tự hào là đơn vị cung cấp các mẫu đồng hồ Casio, Seiko, Orient chính hãng uy tín hàng đầu Việt Nam. Mỗi chiếc đồng hồ trao đi là một lời cam kết về chất lượng và chế độ bảo hành hậu mãi tận tâm nhất.","button_label":"Tìm hiểu thêm","button_href":"\\/lien-he","image_url":"https:\\/\\/images.pexels.com\\/photos\\/277390\\/pexels-photo-277390.jpeg"},"newsletter":{"title":"Đăng ký nhận ưu đãi","description":"Nhận ngay mã giảm giá 10% và cập nhật các thông tin khuyến mãi mới nhất từ Venix Watch.","button_label":"Đăng ký"}}', '2026-05-29 09:09:53'),
